CREATE TABLE Employees (Key INTEGER PRIMARY KEY AUTOINCREMENT, Id TEXT NOT NULL, Name TEXT NOT NULL, HourlyRate TEXT NOT NULL);
CREATE UNIQUE INDEX IX_Employees_Id ON Employees(Id);
CREATE TABLE Builders (Key INTEGER PRIMARY KEY, Specialty TEXT NOT NULL, ExperienceYears INTEGER NOT NULL, SafetyCertificate TEXT NOT NULL, FOREIGN KEY(Key) REFERENCES Employees(Key) ON DELETE CASCADE);
CREATE TABLE Engineers (Key INTEGER PRIMARY KEY, Qualification TEXT NOT NULL, Department TEXT NOT NULL, CompletedProjects INTEGER NOT NULL, FOREIGN KEY(Key) REFERENCES Employees(Key) ON DELETE CASCADE);
CREATE TABLE Projects (Key INTEGER PRIMARY KEY AUTOINCREMENT, Id TEXT NOT NULL, Title TEXT NOT NULL, Budget TEXT NOT NULL, Address TEXT NOT NULL, IsCompleted INTEGER NOT NULL);
CREATE UNIQUE INDEX IX_Projects_Id ON Projects(Id);
CREATE TABLE Profiles (EmployeeKey INTEGER PRIMARY KEY, Phone TEXT NOT NULL, FOREIGN KEY(EmployeeKey) REFERENCES Employees(Key) ON DELETE CASCADE);
CREATE TABLE Tasks (Key INTEGER PRIMARY KEY AUTOINCREMENT, ProjectKey INTEGER NOT NULL, Title TEXT NOT NULL, Done INTEGER NOT NULL, FOREIGN KEY(ProjectKey) REFERENCES Projects(Key) ON DELETE CASCADE);
CREATE INDEX IX_Tasks_ProjectKey ON Tasks(ProjectKey);
CREATE TABLE EmployeeProjects (EmployeeKey INTEGER NOT NULL, ProjectKey INTEGER NOT NULL, PRIMARY KEY(EmployeeKey,ProjectKey), FOREIGN KEY(EmployeeKey) REFERENCES Employees(Key) ON DELETE CASCADE, FOREIGN KEY(ProjectKey) REFERENCES Projects(Key) ON DELETE CASCADE);
CREATE INDEX IX_EmployeeProjects_ProjectKey ON EmployeeProjects(ProjectKey);